// Credenciais Supabase resolvidas em runtime (config.js > meta tags).
// Nenhum valor real vive neste arquivo: anon key é pública por design, mas
// é injetada no deploy para não vazar o projeto via git.
const SUPABASE_URL = (window.TEMTREND_CONFIG?.SUPABASE_URL || '')
  || document.querySelector('meta[name="temtrend-supabase-url"]')?.content?.trim()
  || '';
const SUPABASE_ANON_KEY = (window.TEMTREND_CONFIG?.SUPABASE_ANON_KEY || '')
  || document.querySelector('meta[name="temtrend-supabase-anon-key"]')?.content?.trim()
  || '';
const LOCAL_HOSTS = ['localhost', '127.0.0.1', '[::1]'];
const API_URL = (window.TEMTREND_CONFIG?.API_URL || '')
  || localStorage.getItem('temtrend_api_url')
  || document.querySelector('meta[name="temtrend-api-url"]')?.content?.trim()
  || (LOCAL_HOSTS.includes(location.hostname) ? 'http://localhost:3333' : '');
function requireApiUrl(){if(!API_URL)throw new Error('Serviço indisponível. Configure a API (config.js, meta temtrend-api-url ou localStorage temtrend_api_url).');return API_URL}
if(!API_URL){window.addEventListener('DOMContentLoaded',()=>toast('Serviço indisponível. Tente novamente mais tarde.'))}
if (!window.supabase) { const node = document.getElementById('toast'); if (node) { node.textContent = 'Não foi possível carregar a biblioteca de acesso. Recarregue a página.'; node.classList.remove('hidden'); } throw new Error('Supabase SDK não carregado'); }
if (!SUPABASE_URL || !SUPABASE_ANON_KEY) { window.addEventListener('DOMContentLoaded', () => toast('Serviço indisponível. Tente novamente mais tarde.')); throw new Error('Supabase não configurado. Defina config.js ou meta temtrend-supabase-* no deploy.'); }
const supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
let session; let currentUser; let creatorProductions = []; let activeProductData = null; let activeKit = null; let onboardingStep = 1; let editingPreferences = false; let activeCreatorContentId = null; let productionFilter = 'todos'; let assistantContextProductIds = [];
const onboardingData = { objetivo: '', estilos_conteudo: [], temas_interesse: [] };
try{const savedOnboarding=JSON.parse(localStorage.getItem('temtrend_onboarding')||'null');if(savedOnboarding&&typeof savedOnboarding==='object'){if(typeof savedOnboarding.objetivo==='string')onboardingData.objetivo=savedOnboarding.objetivo;if(Array.isArray(savedOnboarding.estilos_conteudo))onboardingData.estilos_conteudo=savedOnboarding.estilos_conteudo;if(Array.isArray(savedOnboarding.temas_interesse))onboardingData.temas_interesse=savedOnboarding.temas_interesse;if([1,2,3].includes(savedOnboarding.step))onboardingStep=savedOnboarding.step}}catch{}
function persistOnboarding(){try{localStorage.setItem('temtrend_onboarding',JSON.stringify({objetivo:onboardingData.objetivo,estilos_conteudo:onboardingData.estilos_conteudo,temas_interesse:onboardingData.temas_interesse,step:onboardingStep}))}catch{}}
function clearOnboardingCache(){try{localStorage.removeItem('temtrend_onboarding')}catch{}}
const $ = (id) => document.getElementById(id);
const imageFileInput = document.createElement('input'); imageFileInput.id='product-image-file'; imageFileInput.type='file'; imageFileInput.accept='image/jpeg,image/png,image/webp,image/gif'; imageFileInput.title='Ou envie uma imagem'; $('product-image')?.parentElement?.after(imageFileInput); if($('product-image'))$('product-image').required=false;
const esc = (value='') => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function scrollMyProduction(){const section=document.querySelector('#production-section');if(section)section.scrollIntoView({behavior:'smooth',block:'start'})}
const toastQueue=[];let toastTimer=null;function showNextToast(){const node=$('toast');if(!node)return;const next=toastQueue.shift();if(!next){node.classList.add('hidden');toastTimer=null;return}node.textContent=next;node.classList.remove('hidden');toastTimer=setTimeout(showNextToast,3500)}
function toast(message){toastQueue.push(message);if(toastQueue.length>3)toastQueue.shift();if(!toastTimer)showNextToast()}
function userMessage(error,fallback){const message=String(error?.message||'').trim();if(!message)return fallback;if(/failed to fetch|networkerror|typeerror|internal|supabase|gemini|econn|undefined|cannot read|\bnull\b|erro\s*\d|status code 5|stack trace/i.test(message))return fallback;return message}
function emptyStateHtml(title,text,buttonId,buttonLabel){return`<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(text)}</p><button id="${esc(buttonId)}" class="primary" type="button">${esc(buttonLabel)}</button></div>`}
function humanAuthError(error){const message=(error?.message||'').toLowerCase();if(message.includes('invalid login credentials'))return'Email ou senha incorretos.';if(message.includes('email not confirmed'))return'Confirme seu email antes de entrar.';if(message.includes('user already registered')||message.includes('already been registered'))return'Este email já possui uma conta.';if(message.includes('password should be'))return'A senha precisa ter pelo menos 6 caracteres.';if(message.includes('rate limit')||message.includes('too many'))return'Muitas tentativas. Aguarde um pouco e tente novamente.';if(message.includes('expired')||message.includes('invalid token'))return'Este link expirou. Solicite um novo.';if(message.includes('network')||message.includes('fetch'))return'Não foi possível conectar. Verifique sua internet.';return'Não foi possível concluir agora. Tente novamente.'}
function setBusy(form,busy,label){const button=form.querySelector('button[type="submit"]');if(!button)return;if(!button.dataset.label)button.dataset.label=button.textContent;button.disabled=busy;button.textContent=busy?label:button.dataset.label;form.setAttribute('aria-busy',String(busy))}
function showLoginPanel(panel){const copy={login:['SEU PRÓXIMO PASSO','COMECE A VENDER.','Entre para continuar.'],signup:['CONTA GRÁTIS','COMECE A VENDER.','Crie sua conta grátis.'],recovery:['RECUPERAR ACESSO','Esqueceu sua senha?','Digite seu email e enviaremos um link para criar uma nova senha.'],reset:['NOVA SENHA','Crie uma nova senha.','Escolha uma senha segura para continuar.']}[panel];$('login-heading').innerHTML=`<p class="eyebrow">${copy[0]}</p><h1>${copy[1]}</h1><p>${copy[2]}</p>`;$('login-view').classList.toggle('is-signup',panel==='signup');$('login-form').classList.toggle('hidden',panel!=='login');$('signup-form').classList.toggle('hidden',panel!=='signup');$('recovery-form').classList.toggle('hidden',panel!=='recovery');$('reset-form').classList.toggle('hidden',panel!=='reset');$('login-error').textContent='';$('recovery-message').textContent='';const first=$(`${panel==='login'?'email':panel==='signup'?'signup-name':panel==='recovery'?'recovery-email':'new-password'}`);setTimeout(()=>first?.focus(),50)}
async function api(path, options={}){const multipart=options.body instanceof FormData;const headers={...(multipart?{}:{'Content-Type':'application/json'}),...(options.headers||{})};if(session?.access_token)headers.Authorization=`Bearer ${session.access_token}`;let res;try{res=await fetch(requireApiUrl()+path,{...options,headers})}catch{throw new Error('Não foi possível conectar. Verifique sua internet.')}const data=res.status===204?null:await res.json().catch(()=>null);if(!res.ok){const error=new Error(data?.error?.message||'Não conseguimos concluir agora. Tente novamente.');error.code=data?.error?.code;error.status=res.status;throw error}return data}
async function uploadProductImage(file){const form=new FormData();form.append('file',file);const headers={};if(session?.access_token)headers.Authorization=`Bearer ${session.access_token}`;const res=await fetch(`${requireApiUrl()}/admin/products/image`,{method:'POST',headers,body:form});const data=await res.json().catch(()=>null);if(!res.ok)throw new Error(data?.error?.message||`Erro ${res.status}`);return data.imagem_url}
imageFileInput.onchange=async()=>{const file=imageFileInput.files[0];if(!file)return;try{$('product-image').value=await uploadProductImage(file);toast('Imagem enviada ✓')}catch(error){toast(userMessage(error,'Não conseguimos concluir agora. Tente novamente.'))}};
async function loadMe(){const me=await api('/me');currentUser=me;const admin=me.is_admin===true;if(admin){document.body.classList.add('admin-mode');document.body.classList.remove('onboarding-active');$('onboarding').classList.add('hidden');$('creator-content-view').classList.add('hidden');$('admin-view').classList.remove('hidden');await loadAdmin();await Promise.all([loadAdminProducts(),loadAdminCreators()]);return}document.body.classList.remove('admin-mode');$('admin-view').classList.add('hidden');if(!me.onboarding_completo){document.body.classList.add('onboarding-active');$('onboarding').classList.remove('hidden');$('creator-content-view').classList.add('hidden');renderOnboarding();return}document.body.classList.remove('onboarding-active');$('onboarding').classList.add('hidden');$('creator-content-view').classList.remove('hidden');await loadMyContent()}
const FALLBACK_IMAGE='data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20600%22%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M350%20255h100v90H350z%22%20fill%3D%22none%22%20stroke%3D%22%23999%22%20stroke-width%3D%228%22%2F%3E%3Ccircle%20cx%3D%22400%22%20cy%3D%22220%22%20r%3D%2226%22%20fill%3D%22none%22%20stroke%3D%22%23999%22%20stroke-width%3D%228%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22410%22%20text-anchor%3D%22middle%22%20font-family%3D%22Arial%22%20font-size%3D%2224%22%20fill%3D%22%23777%22%3EImagem%20do%20produto%3C%2Ftext%3E%3C%2Fsvg%3E';
function displayProductName(product){const raw=String(product?.nome||'Produto').trim();if(!raw)return'Produto';const cut=raw.split(/\s+[–—\-–|]\s+/)[0].trim();const short=cut||raw;if(short.length<=70)return short;return short.slice(0,67).trim()+'…';}
const productImage=(product)=>esc(product?.imagem_url||FALLBACK_IMAGE);
function productCardsHtml(products){return products.map(p=>{const saved=Boolean(productionForProduct(p.id)?.content_kit_id);const facts=[p.produto_externo_id?`ID ${p.produto_externo_id}`:null,p.preco_texto,p.comissao_percentual!=null?`${p.comissao_percentual}% comissão`:null,p.loja_nome].filter(Boolean).map(esc).join(' · ');const shop=p.tiktok_shop_url?`<a class="product-shop-link" href="${esc(p.tiktok_shop_url)}" target="_blank" rel="noopener noreferrer">Ver no TikTok Shop ↗</a>`:'';return`<article class="product-card"><div class="product-image-wrap"><img class="product-image" src="${productImage(p)}" onerror="this.onerror=null;this.src='${FALLBACK_IMAGE}'" alt="${esc(displayProductName(p))}" loading="lazy"></div><div class="product-body"><span class="product-category">${esc(p.categoria||'Produto')}</span><h3>${esc(displayProductName(p))}</h3>${facts?`<p class="product-facts">${facts}</p>`:''}<p>${esc(p.descricao||'Abra para gerar informações e um roteiro com os dados deste produto.')}</p>${shop}<div class="product-actions"><button class="primary open-product" data-product="${p.id}" type="button" aria-label="Ver produto ${esc(displayProductName(p))}">Ver produto →</button><button class="ghost save-product" data-product="${p.id}" type="button" ${saved?'disabled':''}>${saved?'Produto + Kit salvos ✓':'Salvar + Content Kit'}</button></div></div></article>`}).join('')}
function bindProductCards(root=document){root.querySelectorAll('.open-product').forEach(button=>{button.onclick=()=>openProduct(button.dataset.product)});root.querySelectorAll('.save-product').forEach(button=>{button.onclick=()=>saveProduct(button.dataset.product,button)})}
function productSkeletons(){return Array.from({length:3},()=>'<div class="skeleton-card" aria-hidden="true"><div class="skeleton skeleton-image"></div><div class="skeleton-lines"><span class="skeleton"></span><span class="skeleton"></span><span class="skeleton"></span></div></div>').join('')}
const ASSISTANT_COPY={loading:'A IA está procurando no catálogo...',slow:'Estou conferindo os produtos cadastrados. Isso pode levar alguns segundos.',searching:'Buscando...',idle:'Buscar no catálogo →',emptyTitle:'Nenhum produto encontrado.',emptyText:'Simplifique sua busca ou tente outra ideia: informe categoria, público ou problema que o produto resolve.',emptyAction:'Nova busca',errorTitle:'Não conseguimos concluir sua busca agora.',errorText:'Toque em tentar novamente para refazer a solicitação.',errorAction:'Tentar novamente'};
async function searchWithAssistant(message){const form=$('assistant-form');const button=$('assistant-submit');const response=$('assistant-response');const results=$('assistant-products');button.disabled=true;button.textContent=ASSISTANT_COPY.searching;response.classList.remove('hidden');results.setAttribute('aria-busy','true');$('assistant-message').textContent=ASSISTANT_COPY.loading;results.innerHTML=productSkeletons();const slowMessage=setTimeout(()=>{$('assistant-message').textContent=ASSISTANT_COPY.slow},9000);try{const payload={message};if(assistantContextProductIds.length)payload.product_ids=assistantContextProductIds;const result=await api('/assistant/products',{method:'POST',body:JSON.stringify(payload)});const products=Array.isArray(result.products)?result.products:[];assistantContextProductIds=products.map(product=>product.id);$('assistant-message').textContent=result.message||ASSISTANT_COPY.emptyTitle;if(products.length){results.innerHTML=productCardsHtml(products);bindProductCards(results)}else{results.innerHTML=emptyStateHtml(ASSISTANT_COPY.emptyTitle,ASSISTANT_COPY.emptyText,'assistant-empty-reset',ASSISTANT_COPY.emptyAction);$('assistant-empty-reset').onclick=resetAssistant}}catch(error){$('assistant-message').textContent=ASSISTANT_COPY.errorTitle;results.innerHTML=emptyStateHtml('Tente novamente.',ASSISTANT_COPY.errorText,'assistant-empty-retry',ASSISTANT_COPY.errorAction);$('assistant-empty-retry').onclick=()=>searchWithAssistant(message)}finally{clearTimeout(slowMessage);button.disabled=false;button.textContent=ASSISTANT_COPY.idle;results.removeAttribute('aria-busy');form.removeAttribute('aria-busy')}}
function resetAssistant(){assistantContextProductIds=[];$('assistant-input').value='';$('assistant-response').classList.add('hidden');$('assistant-products').innerHTML='';$('assistant-input').focus()}
$('assistant-form').onsubmit=async(event)=>{event.preventDefault();const message=$('assistant-input').value.trim();if(message.length<3){$('assistant-response').classList.remove('hidden');$('assistant-message').textContent='Descreva com pelo menos 3 caracteres o produto que você procura.';return}event.currentTarget.setAttribute('aria-busy','true');await searchWithAssistant(message)};
document.querySelectorAll('.assistant-examples button').forEach(button=>button.onclick=()=>{$('assistant-input').value=button.dataset.message;assistantContextProductIds=[];$('assistant-form').requestSubmit()});
$('assistant-reset').onclick=resetAssistant;
function showCreatorScreen(screen){['creator-content-view','product-detail-view','kit-detail-view','account-view'].forEach(id=>$(id).classList.toggle('hidden',id!==screen));window.scrollTo({top:0,behavior:'smooth'})}
function kitMeta(kit){return[kit.formato,kit.nivel_dificuldade,kit.duracao_seg?`${kit.duracao_seg}s`:null].filter(Boolean).map(value=>`<span>${esc(value)}</span>`).join('')}
function productionForProduct(productId){return creatorProductions.find(item=>item.product_id===productId||item.products?.id===productId)||null}
function saveProduct(productId,button){if(productionForProduct(productId)?.content_kit_id){button.disabled=true;button.textContent='Produto + Kit salvos ✓';return}openContentKitDialog(productId,'save',false)}
async function chooseContentKit(product,kit){if(!kit){toast('Este produto ainda não possui um Content Kit.');return}let production=productionForProduct(product.id);try{if(!production){production=await api('/creator-content',{method:'POST',body:JSON.stringify({content_kit_id:kit.id})})}else if(!production.content_kit_id){production=await api(`/creator-content/${production.id}/content-kit`,{method:'POST',body:JSON.stringify({content_kit_id:kit.id})})}await loadMyContent();openKit(kit,product);toast('Adicionado à sua produção. ✓')}catch(error){toast(userMessage(error,'Não conseguimos preparar este conteúdo. Tente novamente.'))}}
async function startProductContent(product,kits){const existing=productionForProduct(product.id);if(existing?.content_kit_id){const selected=kits.find(kit=>kit.id===existing.content_kit_id)||existing.content_kits;if(selected){if(existing.status==='salvo')await chooseContentKit(product,selected);else openKit(selected,product);return}}await chooseContentKit(product,kits[0])}
async function openProduct(id){showCreatorScreen('product-detail-view');$('product-detail').innerHTML=productSkeletons();try{activeProductData=await api(`/products/${id}`);const {product,content_kits:kits=[]}=activeProductData;const production=productionForProduct(product.id);const saved=Boolean(production?.content_kit_id);const facts=[product.produto_externo_id?`ID ${product.produto_externo_id}`:null,product.preco_texto,product.comissao_percentual!=null?`${product.comissao_percentual}% comissão`:null,product.loja_nome].filter(Boolean).map(esc).join(' · ');const updatedLine=product.atualizado_em?`<p class="muted"><small>Dados do catálogo atualizados em ${esc(formatUpdated(product.atualizado_em))}.</small></p>`:'';const shopLink=product.tiktok_shop_url?`<a class="product-shop-link" href="${esc(product.tiktok_shop_url)}" target="_blank" rel="noopener noreferrer">Ver produto no TikTok Shop ↗</a>`:'';$('product-detail').innerHTML=`<div class="product-detail-hero"><img src="${productImage(product)}" onerror="this.onerror=null;this.src='${FALLBACK_IMAGE}'" alt="${esc(product.nome)}"><div class="product-detail-copy"><span class="product-category">${esc(product.categoria||'Produto')}</span><h1>${esc(displayProductName(product))}</h1>${String(product.nome||'').trim().length > displayProductName(product).length ? `<p class="muted"><small>Título original: ${esc(product.nome)}</small></p>` : ""}${facts?`<p class="product-facts">${facts}</p>`:''}<p>${esc(product.descricao||'Use os dados confirmados do produto para gerar seu roteiro.')}</p>${updatedLine}${shopLink}<div class="product-detail-primary"><button id="save-product-detail" class="ghost save-product" data-product="${product.id}" type="button" ${saved?'disabled':''}>${saved?'Produto + Kit salvos ✓':'Salvar produto + Content Kit'}</button><button id="create-product-content" class="primary" type="button">${!kits.length?'Criar Content Kit →':production?.content_kit_id&&production.status!=='salvo'?'Ver Content Kit →':'Usar o Content Kit →'}</button>${kits.length?'<button id="generate-new-kit" class="ghost" type="button">Gerar outro roteiro ✦</button>':''}</div></div></div><section class="kits-section"><h2>Content Kits disponíveis</h2><p>O roteiro existente é reutilizado. Gere outra abordagem somente quando precisar de uma nova versão.</p><div class="kits-grid">${kits.length?kits.map(kit=>`<button class="kit-card open-kit" data-kit="${kit.id}" type="button"><div class="kit-meta">${kitMeta(kit)}</div><h3>${esc(kit.titulo)}</h3><p>${esc(kit.descricao||kit.hook||'Abra para ver o plano completo do vídeo.')}</p><strong>Escolher Content Kit →</strong></button>`).join(''):'<div class="empty-state"><h3>Este produto ainda não possui um Content Kit.</h3><p>A IA usará apenas as informações cadastradas para montar hook, roteiro, cenas, copy e CTA.</p><button id="create-kit-for-product" class="primary" type="button">Criar roteiro para este produto →</button></div>'}</div></section>`;$('save-product-detail').onclick=()=>saveProduct(product.id,$('save-product-detail'));$('create-product-content').onclick=()=>kits.length?startProductContent(product,kits):createProductContentKit(product);if($('generate-new-kit'))$('generate-new-kit').onclick=()=>createProductContentKit(product,true);if($('create-kit-for-product'))$('create-kit-for-product').onclick=()=>createProductContentKit(product);document.querySelectorAll('.open-kit').forEach(button=>button.onclick=()=>chooseContentKit(product,kits.find(kit=>kit.id===button.dataset.kit)))}catch{$('product-detail').innerHTML=`<div class="empty-state"><h3>Não conseguimos abrir este produto.</h3><p>Tente novamente em alguns instantes.</p><button id="retry-product" class="primary" type="button">Tentar novamente</button></div>`;$('retry-product').onclick=()=>openProduct(id);toast('Não conseguimos abrir este produto. Tente novamente.')}}

function createProductContentKit(product,forceNew=false){openContentKitDialog(product.id,'kit',forceNew)}
function normalizeScenes(value){if(!value)return[];if(typeof value==='string'){const text=value.trim();if(!text)return[];try{return normalizeScenes(JSON.parse(text))}catch{return text.split(/\n{2,}|\n(?=cena\s*\d+)/i).map(item=>item.trim()).filter(Boolean)}}if(Array.isArray(value))return value.flatMap(item=>normalizeScenes(item));if(typeof value==='object'){if(Array.isArray(value.cenas))return normalizeScenes(value.cenas);const sceneKeys=['mostre','visual','acao','ação','fale','fala','texto','roteiro','descricao','descrição','cena','title','titulo'];if(sceneKeys.some(key=>value[key]!=null))return[value];return Object.values(value).flatMap(item=>normalizeScenes(item))}return[String(value)]}
function sceneParts(scene){if(typeof scene==='string')return{show:scene,say:'',time:'',edit:''};if(!scene||typeof scene!=='object')return{show:'',say:'',time:'',edit:''};const show=scene.mostre||scene.visual||scene.acao||scene['ação']||scene.descricao||scene['descrição']||scene.cena||scene.title||scene.titulo||'';const say=scene.fale||scene.fala||scene.texto||scene.script||scene.narracao||scene['narração']||scene.roteiro||'';const time=scene.tempo||scene.time||scene.duracao||scene['duração']||'';const edit=scene.acao_edicao||scene.acaoEdicao||scene.edicao||scene['edição']||'';if(show||say||time||edit)return{show:String(show),say:String(say),time:String(time),edit:String(edit)};const values=Object.values(scene).filter(value=>['string','number'].includes(typeof value)).map(String);return{show:values.join(' · '),say:'',time:'',edit:''}}
function sceneCopy(scene,index){const parts=sceneParts(scene);return[`CENA ${String(index+1).padStart(2,'0')}${parts.time?` · ${parts.time}`:''}`,parts.show?`MOSTRE:\n${parts.show}`:'',parts.say?`FALE:\n${parts.say}`:'',parts.edit?`AÇÃO / EDIÇÃO:\n${parts.edit}`:''].filter(Boolean).join('\n')}
function sceneHtml(scene,index){const parts=sceneParts(scene);return`<article class="scene-card"><strong>CENA ${String(index+1).padStart(2,'0')}${parts.time?` · ${esc(parts.time)}`:''}</strong>${parts.show?`<div><small>MOSTRE</small><p>${esc(parts.show)}</p></div>`:''}${parts.say?`<div><small>FALE</small><p>${esc(parts.say)}</p></div>`:''}${parts.edit?`<div><small>AÇÃO / EDIÇÃO</small><p>${esc(parts.edit)}</p></div>`:''}</article>`}
function kitCopyText(kit){const scenes=normalizeScenes(kit.cenas).map(sceneCopy).join('\n\n');return[`CONTENT KIT — ${kit.titulo}`,...[['CONCEITO',kit.descricao],['HOOK',kit.hook],['CENAS',scenes],['ROTEIRO',kit.roteiro],['COPY',kit.copy],['CTA',kit.cta],['HASHTAGS',(kit.hashtags||[]).join(' ')],['ÁUDIO',kit.audio_sugerido],['DURAÇÃO',kit.duracao_seg?`${kit.duracao_seg}s`:null]].filter(([,value])=>value).map(([label,value])=>`${label}\n${value}`)].join('\n\n')}
function productionForKit(kit,product){return creatorProductions.find(item=>item.content_kit_id===kit.id||item.content_kits?.id===kit.id)||creatorProductions.find(item=>!item.content_kit_id&&item.product_id===product.id)||null}
const productionSteps=[['salvo','Produto escolhido'],['em_producao','Content Kit escolhido'],['gravado','Vídeo gravado'],['publicado','Publicado']];
function progressIndex(status){return{salvo:1,em_producao:2,gravado:3,publicado:4}[status]||1}
function progressHtml(status){const current=progressIndex(status);return`<div class="production-progress"><strong>${current} de 4 etapas</strong>${productionSteps.map(([,label],index)=>`<span class="${index<current?'done':''}">${index<current?'✓':'○'} ${label}</span>`).join('')}</div>`}
function actionPanel(production){if(!production||production.status==='salvo')return`<h3>Adicionar à minha produção</h3><p>O produto entra na sua produção e o roteiro fica pronto para gravar.</p>${production?progressHtml(production.status):''}<button id="save-content-kit" class="primary" type="button">Adicionar à minha produção →</button>`;if(production.status==='em_producao')return`<span class="production-badge">Content Kit escolhido ✓</span><h3>Produza seu vídeo</h3><div class="production-guidance"><strong>A gravação acontece fora da TemTrend.</strong>Use o hook, o roteiro e as cenas abaixo no aplicativo de câmera que preferir. Depois, volte aqui para atualizar o status.</div>${progressHtml(production.status)}<button id="production-guide" class="primary" type="button">Produzir vídeo →</button><button id="mark-recorded" class="ghost secondary-action" type="button">Marcar como gravado</button>`;if(production.status==='gravado')return`<span class="production-badge">Vídeo gravado ✓</span><h3>Próximo passo</h3><p>Publique o vídeo manualmente e volte para concluir sua produção.</p>${progressHtml(production.status)}<button id="mark-published" class="primary" type="button">Marcar como publicado →</button>`;return`<span class="published-check">✓</span><h3>Conteúdo publicado</h3><p>Sua produção está concluída.</p>${progressHtml(production.status)}${production.published_url?`<a class="primary action-link" href="${esc(production.published_url)}" target="_blank" rel="noopener noreferrer">Ver publicação →</a><button id="add-publication-link" class="ghost" type="button">Alterar link</button>`:`<button id="add-publication-link" class="primary" type="button">Adicionar link do TikTok</button>`}`}
function bindKitActions(production){$('copy-content-kit').onclick=copyCurrentKit;$('copy-hook')?.addEventListener('click',()=>copyField('copy-hook',activeKit.hook,'Hook copiado ✓'));$('copy-roteiro')?.addEventListener('click',()=>copyField('copy-roteiro',activeKit.roteiro,'Roteiro copiado ✓'));$('copy-copy')?.addEventListener('click',()=>copyField('copy-copy',activeKit.copy,'Copy copiada ✓'));$('copy-hashtags')?.addEventListener('click',()=>copyField('copy-hashtags',(activeKit.hashtags||[]).join(' '),'Hashtags copiadas ✓'));if($('save-content-kit'))$('save-content-kit').onclick=saveCurrentKit;if($('production-guide'))$('production-guide').onclick=()=>{document.querySelector('.kit-document')?.scrollIntoView({behavior:'smooth',block:'start'});toast('Use este Content Kit para gravar fora da TemTrend. Nenhum vídeo será enviado.');};if($('mark-recorded'))$('mark-recorded').onclick=()=>updateProduction(production.id,'gravado');if($('mark-published'))$('mark-published').onclick=()=>openPublicationDialog(production.id,production.published_url);if($('add-publication-link'))$('add-publication-link').onclick=()=>openPublicationDialog(production.id,production.published_url)}
function openKit(kit,product){if(!kit)return;activeKit={...kit,product};const production=productionForKit(kit,product);activeCreatorContentId=production?.id||null;showCreatorScreen('kit-detail-view');const scenes=normalizeScenes(kit.cenas);$('kit-detail').innerHTML=`<header class="content-kit-header"><span class="product-category">CONTENT KIT · ${esc(product.nome)}</span><h1>${esc(kit.titulo)}</h1>${kit.descricao?`<p class="preserve-lines">${esc(kit.descricao)}</p>`:''}<div class="kit-meta">${kitMeta(kit)}</div></header><div class="content-kit-layout"><article class="kit-document">${kit.briefing_usuario?`<section class="kit-block"><small>SUAS ORIENTAÇÕES</small><p class="preserve-lines">${esc(kit.briefing_usuario)}</p></section>`:''}${kit.descricao?`<section class="kit-block"><small>BRIEFING RÁPIDO</small><p class="preserve-lines">${esc(kit.descricao)}</p></section>`:''}${kit.hook?`<section class="kit-block hook-block"><div class="block-heading"><small>HOOK</small><button id="copy-hook" type="button">Copiar</button></div><h2>“${esc(kit.hook)}”</h2></section>`:''}${scenes.length?`<section class="kit-block"><small>ROTEIRO POR CENAS</small><div class="scene-list">${scenes.map(sceneHtml).join('')}</div></section>`:''}${kit.roteiro?`<section class="kit-block"><div class="block-heading"><small>ESTRATÉGIA COMPLETA + VARIAÇÕES</small><button id="copy-roteiro" type="button">Copiar roteiro</button></div><p class="preserve-lines">${esc(kit.roteiro)}</p></section>`:''}${kit.copy?`<section class="kit-block"><div class="block-heading"><small>LEGENDA</small><button id="copy-copy" type="button">Copiar legenda</button></div><p>${esc(kit.copy)}</p></section>`:''}${kit.cta?`<section class="kit-block"><small>CTA</small><p>${esc(kit.cta)}</p></section>`:''}${kit.hashtags?.length?`<section class="kit-block"><div class="block-heading"><small>HASHTAGS</small><button id="copy-hashtags" type="button">Copiar hashtags</button></div><div class="hashtag-list">${kit.hashtags.map(tag=>`<span>${esc(tag.startsWith('#')?tag:`#${tag}`)}</span>`).join('')}</div></section>`:''}${kit.audio_sugerido?`<section class="kit-block"><small>ÁUDIO SUGERIDO</small><p>${esc(kit.audio_sugerido)}</p></section>`:''}${kit.duracao_seg?`<section class="kit-block"><small>DURAÇÃO</small><p>${esc(kit.duracao_seg)}s</p></section>`:''}</article><aside class="kit-actions">${actionPanel(production)}<button id="copy-content-kit" class="ghost" type="button">Copiar Content Kit</button><p id="copy-feedback" class="copy-feedback" role="status"></p><button id="go-to-production" class="text-button" type="button">Ir para Minha produção</button></aside></div>`;bindKitActions(production);$('go-to-production').onclick=()=>{showCreatorScreen('creator-content-view');scrollMyProduction()}}
async function copyText(text){try{await navigator.clipboard.writeText(text||'');return true}catch{try{const ta=document.createElement('textarea');ta.value=text||'';ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();return true}catch{return false}}}
async function copyField(buttonId,text,success){const ok=await copyText(text);if(!ok){toast('Não conseguimos copiar. Tente novamente.');return}const button=$(buttonId);const original=button.textContent;button.textContent=success;setTimeout(()=>button.textContent=original,2200)}
async function copyCurrentKit(){const ok=await copyText(kitCopyText(activeKit));if(!ok){toast('Não conseguimos copiar. Tente novamente.');return}$('copy-content-kit').textContent='Content Kit copiado ✓';$('copy-feedback').textContent='O roteiro completo está na sua área de transferência.';setTimeout(()=>{$('copy-content-kit').textContent='Copiar Content Kit';$('copy-feedback').textContent=''},2600)}
async function saveCurrentKit(){const button=$('save-content-kit');button.disabled=true;button.textContent='Adicionando...';try{await chooseContentKit(activeKit.product,activeKit)}catch(error){button.disabled=false;button.textContent='Adicionar à minha produção →';throw error}}
async function updateProduction(id,status){const button=$('mark-recorded');if(button){button.disabled=true;button.textContent='Salvando...'}try{await api(`/creator-content/${id}`,{method:'PATCH',body:JSON.stringify({status})});await loadMyContent();openKit(activeKit,activeKit.product);toast(status==='gravado'?'Vídeo marcado como gravado ✓ Próximo passo: publicar.':'Produção atualizada ✓')}catch(error){if(button)button.disabled=false;toast(userMessage(error,'Não conseguimos atualizar sua produção. Tente novamente.'))}}
function statusLabel(status){return{salvo:'Produto escolhido',em_producao:'Content Kit escolhido',gravado:'Vídeo gravado',publicado:'Publicado ✓'}[status]||status}
function formatUpdated(value){if(!value)return'';return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value))}
function filterCount(filter){if(filter==='todos')return creatorProductions.length;if(filter==='em_producao')return creatorProductions.filter(item=>['salvo','em_producao'].includes(item.status)).length;return creatorProductions.filter(item=>item.status===filter).length}
function updateFilterCounts(){document.querySelectorAll('#production-filters button').forEach(button=>{const base={todos:'Todos',em_producao:'Em produção',gravado:'Gravados',publicado:'Publicados'}[button.dataset.filter]||button.dataset.filter;button.textContent=`${base} (${filterCount(button.dataset.filter)})`})}
function renderProductions(){updateFilterCounts();const data=creatorProductions.filter(item=>productionFilter==='todos'||(productionFilter==='em_producao'&&['salvo','em_producao'].includes(item.status))||item.status===productionFilter);if(!creatorProductions.length){$('my-content').innerHTML='<div class="empty-state"><h3>Você ainda não começou nenhuma produção.</h3><p>Conte o que quer vender e escolha seu primeiro produto.</p><button id="find-products" class="primary" type="button">Encontrar produto →</button></div>';$('find-products').onclick=()=>{$('assistant-input').focus();window.scrollTo({top:0,behavior:'smooth'})};return}if(!data.length){$('my-content').innerHTML='<div class="empty-state"><h3>Nenhum conteúdo neste status.</h3><p>Escolha outro filtro ou encontre um produto para começar.</p><button id="find-products" class="primary" type="button">Encontrar produto →</button></div>';$('find-products').onclick=()=>{$('assistant-input').focus();window.scrollTo({top:0,behavior:'smooth'})};return}$('my-content').innerHTML=data.map(c=>{const kit=c.content_kits||null;const product=c.products||{};const labels={salvo:'Escolher Content Kit →',em_producao:'Produzir vídeo →',publicado:'Ver produção →'};const action=c.status==='gravado'?`<button class="production-action publish-production" data-content="${c.id}" type="button">Marcar como publicado →</button>`:`<button class="production-action continue-production" data-content="${c.id}" type="button">${labels[c.status]||'Ver produção →'}</button>`;return`<article class="production-card"><img src="${productImage(product)}" onerror="this.onerror=null;this.src='${FALLBACK_IMAGE}'" alt="${esc(displayProductName(product))}"><div class="production-info"><h3>${esc(displayProductName(product))}</h3><p class="production-kit-name">${esc(kit?.titulo||'Content Kit ainda não escolhido')}</p><span class="production-status status-${esc(c.status)}">${esc(statusLabel(c.status))}</span><small>Atualizado em ${esc(formatUpdated(c.atualizado_em))}</small>${progressHtml(c.status)}${action}${kit?.hook?`<button class="production-action copy-hook-production" data-content="${c.id}" type="button">Copiar hook</button>`:''}</div></article>`}).join('');document.querySelectorAll('.continue-production').forEach(button=>button.onclick=()=>{const content=creatorProductions.find(item=>item.id===button.dataset.content);if(content.content_kits)openKit(content.content_kits,content.products);else openProduct(content.product_id)});document.querySelectorAll('.copy-hook-production').forEach(button=>button.onclick=async()=>{const content=creatorProductions.find(item=>item.id===button.dataset.content);const ok=await copyText(content?.content_kits?.hook||'');toast(ok?'Hook copiado ✓':'Não conseguimos copiar. Tente novamente.')});document.querySelectorAll('.publish-production').forEach(button=>button.onclick=()=>{const content=creatorProductions.find(item=>item.id===button.dataset.content);openPublicationDialog(content.id,content.published_url||'')})}
async function loadMyContent(){try{creatorProductions=await api('/creator-content');renderProductions()}catch(error){const msg=String(error?.message||'');if(/acesso negado|forbidden/i.test(msg)){$('my-content').innerHTML='<div class="empty-state"><h3>Sua conta está suspensa.</h3><p>Fale com o suporte da TemTrend para regularizar o acesso.</p></div>';return}$('my-content').innerHTML='<div class="empty-state"><h3>Não conseguimos carregar sua produção.</h3><p>Tente novamente em alguns instantes.</p><button id="retry-production" class="primary" type="button">Tentar novamente</button></div>';$('retry-production').onclick=loadMyContent}}
async function loadAdmin(){try{$('metrics').innerHTML='<p class="muted">Carregando métricas...</p>';const d=await api('/admin/dashboard');$('metrics').innerHTML=Object.entries(d).map(([key,value])=>`<div class="metric"><span class="muted">${esc(key.replaceAll('_',' '))}</span><strong>${esc(value)}</strong></div>`).join('')}catch{$( 'metrics').innerHTML='<div class="empty-state"><h3>Não conseguimos carregar as métricas.</h3><p>Tente novamente.</p><button id="retry-metrics" class="primary" type="button">Tentar novamente</button></div>';$('retry-metrics').onclick=loadAdmin}}
async function loadAdminProducts(){try{$('admin-products').innerHTML='<p class="muted">Carregando produtos...</p>';const products=await api('/admin/products');$('admin-products').innerHTML=products.length?products.map(p=>`<div class="admin-row"><div><strong>${esc(p.nome)}</strong><span class="muted">${esc([p.produto_externo_id?`ID ${p.produto_externo_id}`:null,p.categoria||'Sem categoria',p.preco_texto,p.loja_nome,p.status].filter(Boolean).join(' · '))}</span></div><div><button class="ghost edit-product" data-id="${p.id}">Editar</button> <button class="ghost product-status" data-id="${p.id}" data-status="${p.status==='ativo'?'pausado':'ativo'}">${p.status==='ativo'?'Pausar':'Ativar'}</button></div></div>`).join(''):'<p class="muted">Nenhum produto cadastrado.</p>';document.querySelectorAll('.product-status').forEach(b=>b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await api(`/admin/products/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});await loadAdmin();await loadAdminProducts()}catch(err){toast(userMessage(err,'Não conseguimos atualizar o produto.'));b.disabled=false}});document.querySelectorAll('.edit-product').forEach(b=>b.onclick=()=>editProduct(b.dataset.id))}catch{$('admin-products').innerHTML='<div class="empty-state"><h3>Não conseguimos carregar os produtos.</h3><p>Tente novamente.</p><button id="retry-admin-products" class="primary" type="button">Tentar novamente</button></div>';$('retry-admin-products').onclick=loadAdminProducts}}
function setProductField(id,value){const input=$(id);if(input)input.value=value??''}
async function editProduct(id){const data=await api(`/admin/products/${id}`);const product=data.product;$('editing-product-id').value=product.id;setProductField('product-external-id',product.produto_externo_id);setProductField('product-name',product.nome);setProductField('product-category',product.categoria);setProductField('product-store',product.loja_nome);setProductField('product-price-text',product.preco_texto);setProductField('product-commission',product.comissao_percentual);setProductField('product-price-min',product.preco_min_brl);setProductField('product-price-max',product.preco_max_brl);setProductField('product-region',product.pais_regiao);setProductField('product-source-status',product.status_origem);setProductField('product-sales-period',product.unidades_vendidas_periodo);setProductField('product-sales-growth',product.crescimento_vendas_percentual);setProductField('product-sales-total',product.unidades_vendidas_total);setProductField('product-revenue-period',product.receita_periodo_brl);setProductField('product-revenue-total',product.receita_total_brl);setProductField('product-store-sales-total',product.unidades_vendidas_total_loja);setProductField('product-upload-date',product.data_estimada_upload?String(product.data_estimada_upload).slice(0,16):'');setProductField('product-ranking',product.ranking_origem);setProductField('product-description',product.descricao);setProductField('product-image',product.imagem_url);setProductField('product-tiktok-url',product.tiktok_shop_url);setProductField('product-fastmoss-url',product.fastmoss_produto_url);setProductField('product-store-fastmoss-url',product.fastmoss_loja_url);setProductField('product-source',product.fonte_dados);setProductField('product-status',product.status||'ativo');$('product-form-title').textContent='Editar produto';$('product-submit').textContent='Salvar alterações';$('product-cancel-edit').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})}
function cancelProductEdit(){document.getElementById('product-form').reset();$('editing-product-id').value='';$('product-form-title').textContent='Novo produto';$('product-submit').textContent='Adicionar produto';$('product-cancel-edit').classList.add('hidden')}
async function loadAdminCreators(){try{$('admin-creators').innerHTML='<p class="muted">Carregando creators...</p>';const creators=await api('/admin/creators');$('admin-creators').innerHTML=creators.length?creators.map(c=>`<div class="admin-row"><div><strong>${esc(c.nome||c.email||c.user_id)}</strong><span class="muted">${esc(c.email||'')} · ${esc((c.nicho||[]).join(', ')||'Nicho não informado')} · ${esc(c.status)}</span></div><button class="ghost creator-status" data-id="${c.id}" data-status="${c.status==='ativo'?'bloqueado':'ativo'}">${c.status==='ativo'?'Banir':'Desbanir'}</button></div>`).join(''):'<p class="muted">Nenhum creator cadastrado.</p>';document.querySelectorAll('.creator-status').forEach(b=>b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await api(`/admin/creators/${b.dataset.id}/status`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});await loadAdmin();await loadAdminCreators()}catch(err){toast(userMessage(err,'Não conseguimos atualizar o creator.'));b.disabled=false}})}catch{$('admin-creators').innerHTML='<div class="empty-state"><h3>Não conseguimos carregar os creators.</h3><p>Tente novamente.</p><button id="retry-admin-creators" class="primary" type="button">Tentar novamente</button></div>';$('retry-admin-creators').onclick=loadAdminCreators}}
async function start(){const recovery=window.location.hash.includes('type=recovery');const {data}=await supabaseClient.auth.getSession();session=data.session;if(recovery){$('login-view').classList.remove('hidden');$('app-view').classList.add('hidden');showLoginPanel('reset');if(!session)$('login-error').textContent='Se o link expirou, volte e solicite um novo link de recuperação.';return}if(session){$('login-view').classList.add('hidden');$('app-view').classList.remove('hidden');const metadata=session.user.user_metadata||{};const name=metadata.full_name||metadata.name||session.user.email?.split('@')[0]||'Minha conta';$('user-name').textContent=name;$('user-email').textContent=session.user.email||'';$('user-avatar').textContent=name.trim().charAt(0).toUpperCase()||'T';$('dashboard-greeting').textContent=`Olá, ${name.split(' ')[0]}.`;try{await loadMe()}catch{toast('Não conseguimos carregar sua conta. Tente novamente.')}}}
$('login-form').onsubmit=async(e)=>{e.preventDefault();$('login-error').textContent='';setBusy(e.currentTarget,true,'Entrando...');const {data,error}=await supabaseClient.auth.signInWithPassword({email:$('email').value.trim().toLowerCase(),password:$('password').value});if(error){$('login-error').textContent=humanAuthError(error);setBusy(e.currentTarget,false);return}session=data.session;await start();setBusy(e.currentTarget,false)};
async function continueWithGoogle(event){const button=event.currentTarget;button.disabled=true;const original=button.textContent;button.textContent='Conectando...';const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:window.location.origin+window.location.pathname}});if(error){$('login-error').textContent=humanAuthError(error);button.disabled=false;button.textContent=original}}
$('google-login').onclick=continueWithGoogle;
$('signup-google').onclick=$('google-login').onclick;
$('open-signup').onclick=()=>showLoginPanel('signup');
$('signup-to-login').onclick=()=>showLoginPanel('login');
$('signup-form').onsubmit=async(e)=>{e.preventDefault();$('login-error').textContent='';const nome=$('signup-name').value.trim();if(nome.length<2){$('login-error').textContent='Informe seu nome com pelo menos 2 caracteres.';return}setBusy(e.currentTarget,true,'Criando sua conta...');const password=$('signup-password').value;const {data,error}=await supabaseClient.auth.signUp({email:$('signup-email').value.trim().toLowerCase(),password,options:{data:{full_name:nome,name:nome},emailRedirectTo:window.location.origin+window.location.pathname}});if(error){$('login-error').textContent=humanAuthError(error);setBusy(e.currentTarget,false);return}if(data.session){session=data.session;await start();setBusy(e.currentTarget,false);return}showLoginPanel('login');$('recovery-message').textContent='Conta criada. Confira seu email para confirmar e entrar.';setBusy(e.currentTarget,false)};
$('forgot-password').onclick=()=>{$('recovery-email').value=$('email').value;showLoginPanel('recovery')};
$('back-to-login').onclick=()=>showLoginPanel('login');
$('recovery-form').onsubmit=async(e)=>{e.preventDefault();$('recovery-message').textContent='';setBusy(e.currentTarget,true,'Enviando...');const {error}=await supabaseClient.auth.resetPasswordForEmail($('recovery-email').value.trim().toLowerCase(),{redirectTo:window.location.origin+window.location.pathname});setBusy(e.currentTarget,false);if(error){$('login-error').textContent=humanAuthError(error);return}$('recovery-message').textContent='Confira seu email. Enviamos um link para criar sua nova senha.'};
$('reset-form').onsubmit=async(e)=>{e.preventDefault();const password=$('new-password').value;if(password.length<6){$('login-error').textContent='A senha precisa ter pelo menos 6 caracteres.';return}if(password!==$('confirm-password').value){$('login-error').textContent='As senhas não conferem.';return}setBusy(e.currentTarget,true,'Salvando...');const {error}=await supabaseClient.auth.updateUser({password});if(error){$('login-error').textContent=humanAuthError(error);setBusy(e.currentTarget,false);return}await supabaseClient.auth.signOut({scope:'local'});try{localStorage.removeItem('temtrend_onboarding')}catch{}history.replaceState(null,'',window.location.pathname+window.location.search);showLoginPanel('login');$('recovery-message').textContent='Senha atualizada. Entre para continuar.';setBusy(e.currentTarget,false)};
document.querySelectorAll('.password-toggle').forEach(button=>button.onclick=()=>{const input=$(button.dataset.target);const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Ocultar':'Mostrar';button.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha')});
supabaseClient.auth.onAuthStateChange((event,newSession)=>{session=newSession;if(event==='PASSWORD_RECOVERY'){ $('login-view').classList.remove('hidden');$('app-view').classList.add('hidden');showLoginPanel('reset') }if(event==='SIGNED_OUT'){session=null;if(!$('login-view')||$('app-view').classList.contains('hidden'))return;$('app-view').classList.add('hidden');$('login-view').classList.remove('hidden');showLoginPanel('login')}if(event==='TOKEN_REFRESHED'&&newSession){session=newSession}});
window.addEventListener('pageshow',async()=>{try{const {data}=await supabaseClient.auth.getSession();session=data.session;if(!session&&!$('app-view').classList.contains('hidden')){$('app-view').classList.add('hidden');$('login-view').classList.remove('hidden');showLoginPanel('login')}}catch{}});
$('logout').onclick=async()=>{try{await supabaseClient.auth.signOut({scope:'local'})}finally{session=null;try{localStorage.removeItem('temtrend_onboarding')}catch{}location.replace(`${location.pathname}?loggedout=${Date.now()}`)}};$('admin-refresh').onclick=loadAdmin;
