document.querySelectorAll('.app-nav a').forEach(link=>link.addEventListener('click',(event)=>{if(document.body.classList.contains('admin-mode')){event.preventDefault();return}document.querySelectorAll('.app-nav a').forEach(a=>{a.classList.remove('active');a.removeAttribute('aria-current')});link.classList.add('active');link.setAttribute('aria-current','page');document.querySelector('.user-menu')?.removeAttribute('open')}));document.querySelectorAll('.app-logo').forEach(link=>link.addEventListener('click',(event)=>{if(document.body.classList.contains('admin-mode')){event.preventDefault();return}showCreatorScreen('creator-content-view');document.querySelector('.user-menu')?.removeAttribute('open')}));document.querySelector('.app-nav a[href="#assistant-section"]')?.classList.add('active');
function selectedValues(step){return[...document.querySelectorAll(`.onboarding-step[data-step="${step}"] .selected`)].map(node=>node.dataset.value)}
function renderOnboarding(){document.querySelectorAll('.single-select .selection-card').forEach(item=>{const s=item.dataset.value===onboardingData.objetivo;item.classList.toggle('selected',s);item.setAttribute('aria-checked',String(s))});document.querySelectorAll('.onboarding-step[data-step="2"] .multi-select button').forEach(item=>{const s=onboardingData.estilos_conteudo.includes(item.dataset.value);item.classList.toggle('selected',s);item.setAttribute('aria-pressed',String(s))});document.querySelectorAll('.onboarding-step[data-step="3"] .multi-select button').forEach(item=>{const s=onboardingData.temas_interesse.includes(item.dataset.value);item.classList.toggle('selected',s);item.setAttribute('aria-pressed',String(s))});document.querySelectorAll('.onboarding-step').forEach(step=>step.classList.toggle('is-active',Number(step.dataset.step)===onboardingStep));const done=onboardingStep===4;$('onboarding-count').textContent=done?'Pronto':`${onboardingStep} de 3`;$('onboarding-progress-bar').style.width=`${Math.min(onboardingStep,3)/3*100}%`;$('onboarding-back').classList.toggle('hidden',(onboardingStep===1&&!editingPreferences)||done);$('onboarding-back').textContent=onboardingStep===1?'Cancelar':'← Voltar';$('onboarding-skip').classList.toggle('hidden',onboardingStep===1||done);$('onboarding-next').textContent=done?'ENCONTRAR PRODUTOS →':onboardingStep===3?'Começar →':'Continuar →';$('onboarding-next').disabled=onboardingStep===1&&!onboardingData.objetivo;$('onboarding-next').focus({preventScroll:true})}
document.querySelectorAll('.single-select .selection-card').forEach(button=>button.onclick=()=>{document.querySelectorAll('.single-select .selection-card').forEach(item=>{item.classList.remove('selected');item.setAttribute('aria-checked','false')});button.classList.add('selected');button.setAttribute('aria-checked','true');onboardingData.objetivo=button.dataset.value;$('onboarding-next').disabled=false;persistOnboarding()});
document.querySelectorAll('.multi-select button').forEach(button=>{button.setAttribute('aria-pressed','false');button.onclick=()=>{button.classList.toggle('selected');button.setAttribute('aria-pressed',String(button.classList.contains('selected')));if(button.closest('.onboarding-step')){const st=button.closest('.onboarding-step').dataset.step;if(st==='2')onboardingData.estilos_conteudo=selectedValues(2);if(st==='3')onboardingData.temas_interesse=selectedValues(3);persistOnboarding()}}});
async function advanceOnboarding(skip=false){if($('onboarding-next').disabled&&onboardingStep!==1)return;if(onboardingStep===1&&!onboardingData.objetivo)return;if(onboardingStep===2){onboardingData.estilos_conteudo=skip?[]:selectedValues(2);onboardingStep=3;persistOnboarding();renderOnboarding();return}if(onboardingStep===3){onboardingData.temas_interesse=skip?[]:selectedValues(3);persistOnboarding();$('onboarding-next').disabled=true;$('onboarding-next').textContent='Preparando...';try{await api('/creators/onboarding',{method:'POST',body:JSON.stringify(onboardingData)});onboardingStep=4;persistOnboarding();renderOnboarding()}catch{$('onboarding-next').disabled=false;$('onboarding-next').textContent='Começar →';toast('Não conseguimos salvar suas preferências. Tente novamente.')}return}if(onboardingStep===4){editingPreferences=false;document.body.classList.remove('onboarding-active');$('onboarding').classList.add('hidden');clearOnboardingCache();await loadMe();return}onboardingStep+=1;persistOnboarding();renderOnboarding()}
$('onboarding-next').onclick=()=>advanceOnboarding(false);$('onboarding-skip').onclick=()=>advanceOnboarding(true);$('onboarding-back').onclick=()=>{if(onboardingStep===1&&editingPreferences){editingPreferences=false;document.body.classList.remove('onboarding-active');$('onboarding').classList.add('hidden');$('account-view').classList.remove('hidden');return}onboardingStep=Math.max(1,onboardingStep-1);renderOnboarding()};
function optionalNumber(id){const value=$(id).value.trim();return value===''?undefined:Number(value)}
function optionalText(id){const value=$(id).value.trim();return value||undefined}
function productFormInput(){return{produto_externo_id:$('product-external-id').value.trim(),nome:$('product-name').value.trim(),descricao:optionalText('product-description'),categoria:$('product-category').value.trim(),imagem_url:$('product-image').value.trim(),loja_nome:optionalText('product-store'),preco_texto:optionalText('product-price-text'),preco_min_brl:optionalNumber('product-price-min'),preco_max_brl:optionalNumber('product-price-max'),pais_regiao:optionalText('product-region'),comissao_percentual:optionalNumber('product-commission'),unidades_vendidas_periodo:optionalNumber('product-sales-period'),crescimento_vendas_percentual:optionalNumber('product-sales-growth'),unidades_vendidas_total:optionalNumber('product-sales-total'),receita_periodo_brl:optionalNumber('product-revenue-period'),receita_total_brl:optionalNumber('product-revenue-total'),data_estimada_upload:optionalText('product-upload-date'),unidades_vendidas_total_loja:optionalNumber('product-store-sales-total'),fastmoss_produto_url:optionalText('product-fastmoss-url'),tiktok_shop_url:$('product-tiktok-url').value.trim(),fastmoss_loja_url:optionalText('product-store-fastmoss-url'),status_origem:optionalText('product-source-status'),fonte_dados:optionalText('product-source'),ranking_origem:optionalNumber('product-ranking'),status:$('product-status').value,destaque:false,ordem_destaque:0}}
$('product-form').onsubmit=async(e)=>{e.preventDefault();const form=e.currentTarget;setBusy(form,true,'Salvando...');try{const productInput=productFormInput();if(productInput.preco_min_brl!=null&&productInput.preco_max_brl!=null&&productInput.preco_min_brl>productInput.preco_max_brl){toast('Preço mínimo não pode ser maior que o máximo.');return}const productId=$('editing-product-id').value;if(productId){await api(`/admin/products/${productId}`,{method:'PATCH',body:JSON.stringify(productInput)});toast('Produto atualizado ✓')}else{await api('/admin/products',{method:'POST',body:JSON.stringify(productInput)});toast('Produto adicionado ao catálogo ✓')}cancelProductEdit();await loadAdmin();await loadAdminProducts()}catch(err){toast(userMessage(err,'Não conseguimos salvar o produto. Confira os campos e tente novamente.'))}finally{setBusy(form,false)}};
$('product-cancel-edit').onclick=cancelProductEdit;
$('admin-products-refresh').onclick=loadAdminProducts;$('admin-creators-refresh').onclick=loadAdminCreators;
async function loadAccount(){const account=await api('/account');$('account-name').value=account.nome||'';$('account-email').value=account.email||'';$('account-plan-name').textContent=account.plan?.nome||'Plano gratuito';$('account-plan-status').textContent=account.plan?.status==='ativo'?'Ativo':'Inativo';const creator=currentUser?.creator;const preferences=[...(creator?.estilos_conteudo||[]),...(creator?.temas_interesse||[])];$('account-preferences').textContent=preferences.length?preferences.join(' · '):'Você ainda não selecionou temas ou formatos de conteúdo.'}
function editPreferences(){const creator=currentUser?.creator||{};onboardingData.objetivo=creator.objetivo||'comecar_vender';onboardingData.estilos_conteudo=creator.estilos_conteudo||[];onboardingData.temas_interesse=creator.temas_interesse||[];document.querySelectorAll('.single-select .selection-card').forEach(button=>{const selected=button.dataset.value===onboardingData.objetivo;button.classList.toggle('selected',selected);button.setAttribute('aria-checked',String(selected))});document.querySelectorAll('.onboarding-step[data-step="2"] .multi-select button').forEach(button=>{const selected=onboardingData.estilos_conteudo.includes(button.dataset.value);button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('.onboarding-step[data-step="3"] .multi-select button').forEach(button=>{const selected=onboardingData.temas_interesse.includes(button.dataset.value);button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});editingPreferences=true;onboardingStep=1;$('account-view').classList.add('hidden');document.body.classList.add('onboarding-active');$('onboarding').classList.remove('hidden');renderOnboarding()}
function showAccount(){const visible=['admin-view','creator-content-view','product-detail-view','kit-detail-view'].find(id=>!$(id).classList.contains('hidden'))||'creator-content-view';$('account-view').dataset.returnView=visible;['admin-view','creator-content-view','product-detail-view','kit-detail-view'].forEach(id=>$(id).classList.add('hidden'));$('account-view').classList.remove('hidden');$('onboarding').classList.add('hidden');document.querySelector('.user-menu')?.removeAttribute('open');loadAccount().catch(()=>toast('Não conseguimos carregar as configurações.'))}
function hideAccount(){const target=$('account-view').dataset.returnView||'creator-content-view';$('account-view').classList.add('hidden');$(target).classList.remove('hidden')}
$('account-settings').onclick=showAccount;$('back-to-app').onclick=hideAccount;$('edit-preferences').onclick=editPreferences;
$('account-profile-form').onsubmit=async(e)=>{e.preventDefault();const form=e.currentTarget;const nome=$('account-name').value.trim();if(nome.length<2){toast('O nome deve ter pelo menos 2 caracteres.');return}if(nome.length>120){toast('O nome deve ter no máximo 120 caracteres.');return}setBusy(form,true,'Salvando...');try{await api('/account/profile',{method:'PATCH',body:JSON.stringify({nome})});if(currentUser?.creator)currentUser.creator={...currentUser.creator};const first=nome.split(' ')[0];$('user-name').textContent=nome;$('user-avatar').textContent=nome.trim().charAt(0).toUpperCase()||'T';$('dashboard-greeting').textContent=`Olá, ${first}.`;toast('Nome atualizado.')}catch(error){toast(userMessage(error,'Não conseguimos concluir agora. Tente novamente.'))}finally{setBusy(form,false)}};
$('account-password-form').onsubmit=async(e)=>{e.preventDefault();const form=e.currentTarget;const password=$('account-new-password').value;if(password.length<6){toast('A senha precisa ter pelo menos 6 caracteres.');return}if(password!==$('account-confirm-password').value){toast('As senhas não conferem.');return}setBusy(form,true,'Salvando...');const {error}=await supabaseClient.auth.updateUser({password});setBusy(form,false);if(error){toast(userMessage(error,'Não conseguimos atualizar sua senha. Tente novamente.'));return}$('account-password-form').reset();toast('Senha atualizada com sucesso.')};
$('delete-account').onclick=()=>{const dlg=$('delete-account-dialog');if(dlg.open)return;$('delete-account-error').textContent='';dlg.showModal()};
$('cancel-delete-account').onclick=()=>$('delete-account-dialog').close();
$('confirm-delete-account').onclick=async()=>{const btn=$('confirm-delete-account');if(btn.disabled)return;btn.disabled=true;const original=btn.textContent;btn.textContent='Excluindo...';try{await api('/account',{method:'DELETE'});await supabaseClient.auth.signOut({scope:'local'});try{localStorage.removeItem('temtrend_onboarding')}catch{}location.replace(`${location.pathname}?deleted=${Date.now()}`)}catch(error){$('delete-account-error').textContent=userMessage(error,'Não conseguimos concluir agora. Tente novamente.');btn.disabled=false;btn.textContent=original}};
if(new URLSearchParams(location.search).get('mode')==='signup')showLoginPanel('signup');

function openContentKitDialog(productId,mode='kit',forceNew=false){const dlg=$('content-kit-dialog');if(dlg.open)return;document.querySelectorAll('.briefing-suggestions button.selected').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});$('content-kit-product-id').value=productId;$('content-kit-mode').value=mode;$('content-kit-force-new').value=String(forceNew);$('content-kit-briefing').value='';$('content-kit-character-count').textContent='0 de 1500 caracteres';$('content-kit-error').textContent='';const submit=$('content-kit-form').querySelector('button[type="submit"]');submit.textContent=mode==='save'?'Salvar produto e criar meu kit →':forceNew?'Gerar outra versão →':'Gerar meu Content Kit →';submit.dataset.label=submit.textContent;dlg.showModal();setTimeout(()=>$('content-kit-briefing').focus(),50)}
$('content-kit-briefing').addEventListener('input',()=>{$('content-kit-character-count').textContent=`${$('content-kit-briefing').value.length} de 1500 caracteres`});
document.querySelectorAll('.briefing-suggestions button').forEach(button=>{button.setAttribute('aria-pressed','false');button.onclick=()=>{const input=$('content-kit-briefing');const suggestion=button.dataset.briefing;const selected=button.classList.toggle('selected');button.setAttribute('aria-pressed',String(selected));const current=input.value.trim();if(selected){if(!current.includes(suggestion))input.value=current?`${current}. ${suggestion}`:suggestion}else if(current.includes(suggestion)){input.value=current.replace(suggestion,'').replace(/\.\s*\./g,'.').replace(/\s{2,}/g,' ').trim().replace(/^\.\s*/,'')}input.dispatchEvent(new Event('input'));input.focus()}});
$('content-kit-form').onsubmit=async(event)=>{event.preventDefault();const form=event.currentTarget;const productId=$('content-kit-product-id').value;const mode=$('content-kit-mode').value;const forceNew=$('content-kit-force-new').value==='true';const briefing=$('content-kit-briefing').value.trim();$('content-kit-error').textContent='';setBusy(form,true,mode==='save'?'Salvando e gerando seu Content Kit...':'Gerando seu Content Kit...');try{if(mode==='save'){await api('/creator-content',{method:'POST',body:JSON.stringify({product_id:productId,content_kit_briefing:briefing||undefined})});await loadMyContent();document.querySelectorAll(`.save-product[data-product="${productId}"]`).forEach(item=>{item.disabled=true;item.textContent='Produto + Kit salvos ✓'});$('content-kit-dialog').close();toast('Produto e Content Kit exclusivo salvos ✓')}else{const result=await api(`/products/${productId}/content-kit`,{method:'POST',body:JSON.stringify({force_new:forceNew,instructions:briefing||undefined})});await loadMyContent();$('content-kit-dialog').close();const product=activeProductData?.product?.id===productId?activeProductData.product:(await api(`/products/${productId}`)).product;if(result?.content_kit)openKit(result.content_kit,product);else await openProduct(productId);toast(result?.fallback?'IA indisponível — salvamos um roteiro base. Gere outra versão depois.':result?.created?'Seu Content Kit exclusivo foi criado ✓':'Seu Content Kit existente foi reutilizado ✓')}}catch(error){const code=error?.code;$('content-kit-error').textContent=code==='AI_UNAVAILABLE'?'A IA está indisponível agora. Tente novamente em alguns minutos.':code==='SERVICE_UNAVAILABLE'?'Não conseguimos gerar seu Content Kit agora. Tente novamente em alguns segundos.':userMessage(error,'Não conseguimos preparar seu Content Kit agora. Tente novamente.')}finally{setBusy(form,false)}};
$('close-content-kit-dialog').onclick=()=>$('content-kit-dialog').close();

function openPublicationDialog(contentId,url=''){const dlg=$('publication-dialog');if(dlg.open)return;$('publication-content-id').value=contentId;$('publication-url').value=url||'';$('publication-error').textContent='';dlg.showModal();setTimeout(()=>$('publication-url').focus(),50)}
function validTikTokUrl(value){if(!value)return true;try{const host=new URL(value).hostname.toLowerCase();return host==='tiktok.com'||host.endsWith('.tiktok.com')||host==='vm.tiktok.com'||host==='vt.tiktok.com'||host==='m.tiktok.com'||host==='www.tiktok.com'}catch{return false}}
$('publication-form').onsubmit=async(event)=>{event.preventDefault();const form=event.currentTarget;const value=$('publication-url').value.trim();if(!validTikTokUrl(value)){$('publication-error').textContent='Cole um link válido do TikTok.';return}setBusy(form,true,'Salvando...');try{const contentId=$('publication-content-id').value;await api(`/creator-content/${contentId}`,{method:'PATCH',body:JSON.stringify({status:'publicado',published_url:value||null})});$('publication-dialog').close();await loadMyContent();const updated=creatorProductions.find(item=>item.id===contentId);if(updated?.content_kits)openKit(updated.content_kits,updated.products||activeKit?.product||{});else{showCreatorScreen('creator-content-view');scrollMyProduction()}toast(value?'Publicado ✓ Link salvo.':'Conteúdo marcado como publicado.')}catch{$('publication-error').textContent='Não conseguimos salvar a publicação. Tente novamente.'}finally{setBusy(form,false)}};
$('close-publication-dialog').onclick=()=>$('publication-dialog').close();
document.querySelectorAll('#production-filters button').forEach(button=>{button.setAttribute('aria-pressed',String(button.classList.contains('active')));button.onclick=()=>{productionFilter=button.dataset.filter;document.querySelectorAll('#production-filters button').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button))});renderProductions()}});
